import os, re, json, hmac, hashlib, datetime, urllib.parse, urllib.request
from urllib.parse import urlparse

j = _item['json']
slug = j.get('slug')
if not slug:
    return {'success': False, 'error': 'no_slug'}
source_bucket = j.get('source_bucket', 'mottruyen-refactored')
output_filename = (j.get('output_filename') or 'character_bible.md').strip()
style_guide_bucket = j.get('style_guide_bucket', 'style-guide')
genre_detect_chars = int(j.get('genre_detect_chars') or 4000)
overwrite = bool(j.get('overwrite') or False)

endpoint = os.environ.get('MINIO_ENDPOINT', 'http://minio:9000')
access_key = os.environ['MINIO_ACCESS_KEY']
secret_key = os.environ['MINIO_SECRET_KEY']
region = os.environ.get('MINIO_REGION', 'us-east-1')
VLLM_URL = os.environ.get('VLLM_BASE_URL', 'http://vllm:8000/v1').rstrip('/') + '/chat/completions'
VLLM_KEY = os.environ.get('VLLM_API_KEY', 'vllm-local')
MODEL = os.environ.get('VLLM_MODEL', 'Qwen/Qwen3.6-35B-A3B-FP8')
MAX_MODEL_LEN = int(j.get('max_model_len') or os.environ.get('VLLM_MAX_MODEL_LEN', '131072'))
SAFETY_MARGIN = 100  # token margin (nhỏ vì dùng /tokenize chính xác)

def _sign(method, bucket, key='', payload=b''):
    parsed = urlparse(endpoint); host = parsed.netloc
    now = datetime.datetime.now(datetime.UTC)
    amzdate = now.strftime('%Y%m%dT%H%M%SZ'); datestamp = now.strftime('%Y%m%d')
    ph = hashlib.sha256(payload).hexdigest() if payload else 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'
    cu = '/' + bucket + ('/' + urllib.parse.quote(key, safe='/') if key else '')
    ch = f'host:{host}\nx-amz-content-sha256:{ph}\nx-amz-date:{amzdate}\n'
    sh = 'host;x-amz-content-sha256;x-amz-date'
    cr = f'{method}\n{cu}\n\n{ch}\n{sh}\n{ph}'
    cs = f'{datestamp}/{region}/s3/aws4_request'
    sts = f'AWS4-HMAC-SHA256\n{amzdate}\n{cs}\n{hashlib.sha256(cr.encode()).hexdigest()}'
    def _h(k, m): return hmac.new(k, m.encode(), hashlib.sha256).digest()
    kd = _h(('AWS4' + secret_key).encode(), datestamp); kr = _h(kd, region); ks = _h(kr, 's3'); ki = _h(ks, 'aws4_request')
    sig = hmac.new(ki, sts.encode(), hashlib.sha256).hexdigest()
    auth = f'AWS4-HMAC-SHA256 Credential={access_key}/{cs}, SignedHeaders={sh}, Signature={sig}'
    return f'{endpoint}{cu}', {'Host': host, 'X-Amz-Date': amzdate, 'X-Amz-Content-SHA256': ph, 'Authorization': auth}

def s3_get(bucket, key):
    url, h = _sign('GET', bucket, key)
    with urllib.request.urlopen(urllib.request.Request(url, headers=h), timeout=120) as r:
        return r.read()

def s3_head(bucket, key):
    url, h = _sign('HEAD', bucket, key)
    try:
        with urllib.request.urlopen(urllib.request.Request(url, method='HEAD', headers=h), timeout=30) as r:
            return int(r.headers.get('Content-Length') or 0)
    except urllib.error.HTTPError as e:
        if e.code == 404: return None
        raise

def s3_put(bucket, key, body, ctype):
    url, h = _sign('PUT', bucket, key, payload=body)
    h['Content-Type'] = ctype
    with urllib.request.urlopen(urllib.request.Request(url, data=body, method='PUT', headers=h), timeout=180) as r:
        return r.status

def vllm_chat(system, user, max_tokens=20000, temperature=0.4, json_mode=False):
    payload = {
        'model': MODEL,
        'messages': [{'role': 'system', 'content': system}, {'role': 'user', 'content': user}],
        'temperature': temperature, 'max_tokens': max_tokens,
        'chat_template_kwargs': {'enable_thinking': False},
    }
    if json_mode:
        payload['response_format'] = {'type': 'json_object'}
    body = json.dumps(payload).encode('utf-8')
    req = urllib.request.Request(VLLM_URL, data=body, headers={'Content-Type': 'application/json', 'Authorization': f'Bearer {VLLM_KEY}'})
    with urllib.request.urlopen(req, timeout=1800) as r:
        d = json.loads(r.read())
    return d['choices'][0]['message'].get('content') or ''

def count_tokens(text):
    body = json.dumps({'model': MODEL, 'prompt': text}).encode('utf-8')
    url = VLLM_URL.replace('/chat/completions', '/tokenize')
    req = urllib.request.Request(url, data=body, headers={'Content-Type': 'application/json', 'Authorization': f'Bearer {VLLM_KEY}'})
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            d = json.loads(r.read())
        return int(d.get('count') or len(d.get('tokens') or []))
    except Exception:
        return None

def extract_json(s):
    s = re.sub(r'<think>.*?</think>', '', s, flags=re.S)
    m = re.search(r'\{[^{}]*\}', s, re.S)
    if m:
        try: return json.loads(m.group(0))
        except Exception: return None
    return None

# Skip check
if not overwrite:
    sz = s3_head(source_bucket, f'{slug}/{output_filename}')
    if sz and sz > 500:
        return {'success': True, 'slug': slug, 'skipped': True, 'reason': 'already_exists',
                'target': f'{source_bucket}/{slug}/{output_filename}', 'existing_size': sz}

# Fetch story
try:
    raw = s3_get(source_bucket, f'{slug}/{slug}_full.txt').decode('utf-8')
except Exception as e:
    return {'success': False, 'slug': slug, 'error': f'fetch_failed: {type(e).__name__}: {e}'}
if not raw or len(raw.strip()) < 200:
    return {'success': False, 'slug': slug, 'error': 'text_too_short'}

# ===== Step 1: Detect genre =====
GENRE_SYSTEM = 'Bạn phân loại truyện tiếng Việt. Trả về STRICT JSON, không markdown, không giải thích.'
GENRE_USER = (
    'Đọc đoạn đầu truyện dưới đây và phân loại genre.\n'
    'Các genre hỗ trợ:\n'
    '- "co-trang": truyện phong kiến/cổ đại (có vua/hoàng đế/hoàng hậu, hầu phủ, công chúa, tướng quân, hậu cung, thanh kiếm, hanfu, triều đình...)\n'
    '- "hien-dai": truyện hiện đại (có điện thoại, xe hơi, công ty, đại học, internet, thành phố hiện đại...)\n'
    'Chỉ chọn 1, trả JSON: {"genre": "co-trang"} hoặc {"genre": "hien-dai"}\n\n'
    'Đoạn đầu truyện:\n' + raw[:genre_detect_chars]
)
detected_genre = 'co-trang'
try:
    out = vllm_chat(GENRE_SYSTEM, GENRE_USER, max_tokens=200, temperature=0.1, json_mode=True)
    parsed = extract_json(out) or {}
    g = (parsed.get('genre') or '').strip().lower()
    if g in ('co-trang', 'hien-dai'):
        detected_genre = g
except Exception as e:
    pass  # fallback co-trang

# ===== Step 2: Load style guide from style-guide bucket =====
try:
    _gmap = json.loads(j.get('guide_filename_map') or '{}')
    if not isinstance(_gmap, dict): _gmap = {}
except Exception:
    _gmap = {}
# Default mapping if param empty
if not _gmap:
    _gmap = {'co-trang': 'historical_summary_guide.md', 'hien-dai': 'modern_summary_guide.md'}
guide_key = _gmap.get(detected_genre) or f'{detected_genre}.md'
guide_content = None
guide_used = None
try:
    guide_content = s3_get(style_guide_bucket, guide_key).decode('utf-8')
    guide_used = guide_key
except Exception:
    # Fallback to default.md
    try:
        guide_content = s3_get(style_guide_bucket, 'default.md').decode('utf-8')
        guide_used = 'default.md'
    except Exception:
        return {'success': False, 'slug': slug, 'error': 'no_guide_found',
                'detected_genre': detected_genre, 'tried': [guide_key, 'default.md'],
                'hint': f'Upload guide vào {style_guide_bucket}/{guide_key} hoặc {style_guide_bucket}/default.md'}

# ===== Step 3: Summarize using guide =====
SYSTEM = ('Bạn là biên tập viên/AI tổng hợp truyện tiếng Việt. Tuân thủ CHÍNH XÁC hướng dẫn trong user prompt. '
    'TRẢ VỀ DUY NHẤT markdown thuần — KHÔNG kèm preamble, KHÔNG markdown fence ```.')

USER = guide_content.strip() + '\n\n---\n\nTRUYỆN:\n' + raw

# Estimate input tokens (VN ~1.7 chars/token for Qwen) và tính max_out an toàn
# Đếm input tokens CHÍNH XÁC qua /tokenize endpoint (chính xác hơn ước lượng char-based)
exact = count_tokens(SYSTEM + '\n' + USER)
if exact is not None:
    input_tokens = exact + 60  # buffer cho chat template wrapping (system+user roles)
    est_method = 'tokenize'
else:
    # Fallback: 1.5 tokens/char (chặt cho VN cổ trang dấu)
    input_tokens = (len(SYSTEM) + len(USER)) * 15 // 10
    est_method = 'estimate'
est_input_tokens = input_tokens  # giữ tên cũ cho error trace
max_out = MAX_MODEL_LEN - input_tokens - SAFETY_MARGIN
if max_out < 2000:
    return {'success': False, 'slug': slug,
            'error': f'input_too_long: est {est_input_tokens} tokens + safety {SAFETY_MARGIN} không còn chỗ output (max_model_len={MAX_MODEL_LEN}). Truyện cần được rút gọn hoặc tăng max-model-len.',
            'detected_genre': detected_genre, 'guide_used': guide_used,
            'source_size': len(raw), 'guide_size': len(guide_content)}
max_out = min(max_out, 20000)  # cap upper bound vì output > 20K hiếm khi cần
try:
    md = vllm_chat(SYSTEM, USER, max_tokens=max_out, temperature=0.4)
except urllib.error.HTTPError as e:
    err_body = ''
    try: err_body = e.read().decode('utf-8', errors='replace')[:500]
    except Exception: pass
    return {'success': False, 'slug': slug,
            'error': f'llm_http_{e.code}: {err_body}',
            'detected_genre': detected_genre, 'guide_used': guide_used,
            'est_input_tokens': est_input_tokens, 'max_out_requested': max_out}
except Exception as e:
    return {'success': False, 'slug': slug, 'error': f'llm_failed: {type(e).__name__}: {e}',
            'detected_genre': detected_genre, 'guide_used': guide_used,
            'est_input_tokens': est_input_tokens, 'max_out_requested': max_out}

md = md.strip()
md = re.sub(r'^```(?:markdown|md)?\s*\n', '', md)
md = re.sub(r'\n```\s*$', '', md)

if not md or len(md) < 200:
    return {'success': False, 'slug': slug, 'error': 'llm_output_too_short',
            'detected_genre': detected_genre, 'guide_used': guide_used, 'preview': md[:200]}

# Prepend metadata header
header = f'<!--\nslug: {slug}\ngenre: {detected_genre}\nguide: {guide_used}\nmodel: {MODEL}\nsource: {source_bucket}/{slug}/{slug}_full.txt\n-->\n\n'
final = header + md

body = final.encode('utf-8')
key = f'{slug}/{output_filename}'
try:
    status = s3_put(source_bucket, key, body, 'text/markdown; charset=utf-8')
except Exception as e:
    return {'success': False, 'slug': slug, 'error': f's3_put_failed: {type(e).__name__}: {e}'}

return {
    'success': True,
    'slug': slug,
    'index': j.get('index'),
    'total': j.get('total'),
    'detected_genre': detected_genre,
    'guide_used': f'{style_guide_bucket}/{guide_used}',
    'output': f'{source_bucket}/{key}',
    'output_size': len(body),
    'model': MODEL,
    'source_size': len(raw),
    'status': status,
    'preview': md[:300],
}
